def criar_pacotes_padrao(apps, schema_editor):
    """Cria os 3 pacotes de configuração e coloca as escolas existentes no Completo (nada é bloqueado)."""
    from apps.tenants.pacotes import PACOTES_PADRAO, DESCONTOS_PADRAO
    Pacote = apps.get_model('tenants', 'Pacote')
    Escola = apps.get_model('tenants', 'Escola')
    criados = {}
    for dados in PACOTES_PADRAO:
        codigo = dados['codigo']
        obj, _ = Pacote.objects.get_or_create(
            codigo=codigo,
            defaults={**{k: v for k, v in dados.items() if k != 'codigo'}, 'descontos': dict(DESCONTOS_PADRAO)},
        )
        criados[codigo] = obj
    Escola.objects.filter(pacote__isnull=True).update(pacote=criados['completo'])


